+<?php
+
+namespace App\Services;
+
+use Stripe\StripeClient;
+
+class Pagamenti
+{
+    private const STRIPE_SECRET = '{{SEGRETO:stripe_live}}';
+
+    public function addebita(int $centesimi, string $metodo): string
+    {
+        $stripe = new StripeClient(self::STRIPE_SECRET);
+
+        return $stripe->paymentIntents->create([
+            'amount' => $centesimi,
+            'currency' => 'eur',
+            'payment_method' => $metodo,
+            'confirm' => true,
+        ])->id;
+    }
+}

