+use App\Policies\OrdinePolicy;
+use Tests\TestCase;
+
+class OrdinePolicyTest extends TestCase
+{
+    public function test_il_proprietario_puo_annullare(): void
+    {
+        $utente = Utente::factory()->make(['id' => 7]);
+        $ordine = Ordine::factory()->make(['utente_id' => 7]);
+
+        $this->assertTrue((new OrdinePolicy)->annulla($utente, $ordine));
+    }
