+<?php
+
+namespace App\Console\Commands;
+
+use App\Models\Ordine;
+use Illuminate\Console\Command;
+
+class ControllaTotali extends Command
+{
+    protected $signature = 'ordini:controlla';
+
+    protected $description = 'Confronta i totali degli ordini con la somma delle righe';
+
+    public function handle(): int
+    {
+        $sbagliati = 0;
+        foreach (Ordine::with('righe')->lazy() as $ordine) {
+            $atteso = $ordine->righe->sum(fn ($r) => $r->prezzo * $r->quantita);
+            if ($ordine->totale !== $atteso) {
+                $this->line("Ordine {$ordine->id}: {$ordine->totale} invece di {$atteso}");
+                $sbagliati++;
+            }
+        }
+        $this->info("Ordini con il totale sbagliato: {$sbagliati}");
+
+        return $sbagliati === 0 ? self::SUCCESS : self::FAILURE;
+    }
+}

